class Solution {
public:
    int calculate(string s) {
        long long num = 0;
        char sign = '+';
        vector<int> st;
        for (int i = 0; i < (int)s.size(); i++) {
            char c = s[i];
            if (isdigit(c)) num = num * 10 + (c - '0');
            if ((!isdigit(c) && c != ' ') || i == (int)s.size() - 1) {
                if (sign == '+') st.push_back((int)num);
                else if (sign == '-') st.push_back((int)-num);
                else if (sign == '*') {
                    int top = st.back(); st.pop_back();
                    st.push_back(top * (int)num);
                } else if (sign == '/') {
                    int top = st.back(); st.pop_back();
                    st.push_back(top / (int)num);
                }
                sign = c;
                num = 0;
            }
        }
        int res = 0;
        for (int x : st) res += x;
        return res;
    }
};

class Solution {
    public int calculate(String s) {
        int num = 0;
        char sign = '+';
        java.util.ArrayDeque<Integer> st = new java.util.ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) num = num * 10 + (c - '0');
            if ((!Character.isDigit(c) && c != ' ') || i == s.length() - 1) {
                if (sign == '+') st.push(num);
                else if (sign == '-') st.push(-num);
                else if (sign == '*') st.push(st.pop() * num);
                else if (sign == '/') st.push(st.pop() / num);
                sign = c;
                num = 0;
            }
        }
        int res = 0;
        for (int x : st) res += x;
        return res;
    }
}

var calculate = function(s) {
    let num = 0;
    let sign = '+';
    const st = [];
    for (let i = 0; i < s.length; i++) {
        const c = s[i];
        if (c >= '0' && c <= '9') num = num * 10 + Number(c);
        if ((c !== ' ' && (c < '0' || c > '9')) || i === s.length - 1) {
            if (sign === '+') st.push(num);
            else if (sign === '-') st.push(-num);
            else if (sign === '*') st.push(st.pop() * num);
            else if (sign === '/') st.push(Math.trunc(st.pop() / num));
            sign = c;
            num = 0;
        }
    }
    return st.reduce((a, b) => a + b, 0);
};
